using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SilencingAuraEffect", menuName = "Data/Battle/Effects/Enemy/SilencingAura Effect")]
public class SilencingAuraEffect : AuraEffects
{
	[Header("Silencing Aura Effect")]
	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private bool checkIfOtherSentinelWithSameEffect;

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueStartOfTurnAction(SilenceCoroutine(effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		if (checkIfOtherSentinelWithSameEffect)
		{
			List<GameObject> corruptedAnimalsNotCorruptionSource = currentCorruptedAnimals.GetCorruptedAnimalsNotCorruptionSource();
			for (int i = 0; i < corruptedAnimalsNotCorruptionSource.Count; i++)
			{
				if (!(corruptedAnimalsNotCorruptionSource[i] == effectOwner) && corruptedAnimalsNotCorruptionSource[i].GetComponent<CorruptedAnimalEffects>().IsEffectActive(this, activateFeedback: false))
				{
					return;
				}
			}
		}
		playerCurrentRunes.SilencingAuraRemovedActivateRunes();
	}

	public IEnumerator SilenceCoroutine(GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			yield return new WaitForSeconds(0.3f);
			effectOwner.GetComponent<UnitEffects>();
			currentCorruptedAnimals.PlayFeedbackOfCorruptedAnimalWithSilencingAura();
			playerCurrentRunes.DisableAllRunes();
			yield return new WaitForSeconds(0.6f);
		}
	}
}
